"""Store 11 keeps exact pre-Frame v1 bytes until its coordinated replacement."""

import json
from dataclasses import replace
from datetime import datetime, timezone
from pathlib import Path

import pytest

from marivo.analysis.core.artifact_data import (
    ArtifactManifest,
    BuiltinCalendarData,
    CalendarDataAxis,
    FrozenCalendarData,
)
from marivo.analysis.materialization.contracts import canonical_json
from marivo.analysis.materialization.errors import IntegrityError
from marivo.analysis.materialization.terminal_protocol import decode, encode

# Generated by the exact f24c008281 baseline codec, before S1 schema extensions.
FROZEN = Path(__file__).with_name("terminal_v1_frozen.json").read_text().strip()


def test_pre_frame_v1_bytes_decode_and_reencode_identically() -> None:
    saved = decode(FROZEN, ArtifactManifest)
    assert encode(saved) == FROZEN
    assert tuple(axis.name for axis in saved.data.schema.axes) == ("", "")
    assert all(axis.at is None for axis in saved.data.schema.axes)
    calendar = saved.data.schema.axes[1]
    assert isinstance(calendar, CalendarDataAxis) and calendar.frozen is None
    assert saved.data.schema.value_paths == saved.data.schema.presence_paths == ()
    wire = json.loads(encode(saved))
    schema = wire["value"]["fields"]["data"]["fields"]["schema"]["fields"]
    assert set(schema) == {"axes", "values", "presence", "projection_columns"}
    assert set(schema["axes"][0]["fields"]) == {"token", "columns", "kind"}
    assert set(schema["axes"][1]["fields"]) == {"token", "columns", "kind", "timezone"}


@pytest.mark.parametrize("changed", ["name", "at", "frozen", "value_paths", "presence_paths"])
def test_v1_writer_rejects_new_nondefault_frame_metadata(changed: str) -> None:
    saved = decode(FROZEN, ArtifactManifest)
    schema = saved.data.schema
    if changed in ("name", "at"):
        axis = (
            replace(schema.axes[0], name="customer")
            if changed == "name"
            else replace(schema.axes[0], at=datetime(2026, 10, 19, tzinfo=timezone.utc))
        )
        schema = replace(schema, axes=(axis, schema.axes[1]))
    elif changed == "frozen":
        calendar = schema.axes[1]
        assert isinstance(calendar, CalendarDataAxis)
        schema = replace(
            schema,
            axes=(
                schema.axes[0],
                replace(
                    calendar,
                    frozen=FrozenCalendarData(
                        BuiltinCalendarData("month", 1), "calendar.directory"
                    ),
                ),
            ),
        )
    elif changed == "value_paths":
        schema = replace(schema, value_paths=(("revenue",),))
    else:
        schema = replace(schema, presence_paths=(("left_present",),))
    with pytest.raises(IntegrityError, match="new Frame metadata"):
        encode(replace(saved, data=replace(saved.data, schema=schema)))


@pytest.mark.parametrize("changed", ["name", "at", "frozen", "value_paths", "presence_paths"])
def test_v1_reader_rejects_new_wire_fields_even_when_default(changed: str) -> None:
    wire = json.loads(FROZEN)
    schema = wire["value"]["fields"]["data"]["fields"]["schema"]["fields"]
    fieldsets = {
        "name": schema["axes"][0]["fields"],
        "at": schema["axes"][0]["fields"],
        "frozen": schema["axes"][1]["fields"],
        "value_paths": schema,
        "presence_paths": schema,
    }
    defaults: dict[str, object] = {
        "name": "",
        "at": None,
        "frozen": None,
        "value_paths": [],
        "presence_paths": [],
    }
    fieldsets[changed][changed] = defaults[changed]
    with pytest.raises(IntegrityError, match="unknown or missing metadata members"):
        decode(canonical_json(wire), ArtifactManifest)
